/** חישובי המחשבונים — פונקציות טהורות (נבדקות ב-QA). */

/** לוח שפיצר: P = L·r·(1+r)^n / ((1+r)^n − 1), r = ריבית שנתית/1200, n = שנים×12. null אם הקלט לא תקין. */
export function spitzer(amount: number, years: number, ratePct: number) {
  if (!(amount > 0) || !(years > 0) || !(ratePct >= 0) || ratePct > 50) return null;
  const n = Math.round(years * 12);
  const r = ratePct / 1200;
  const monthly = r === 0 ? amount / n : (amount * r * (1 + r) ** n) / ((1 + r) ** n - 1);
  const total = monthly * n;
  return { monthly, total, interest: total - amount, n };
}

/** תשואה: ברוטו = שכ"ד שנתי מלא / מחיר; נטו = (שכ"ד בפועל − הוצאות) / (מחיר + עלויות רכישה). */
export function rentalYield(price: number, rent: number, expenses = 0, vacancyMonths = 0, costs = 0) {
  if (!(price > 0) || !(rent > 0)) return null;
  const exp = expenses > 0 ? expenses : 0, vac = Math.min(Math.max(vacancyMonths || 0, 0), 12), c = costs > 0 ? costs : 0;
  const grossRent = rent * 12;
  const collected = rent * (12 - vac);
  const net = collected - exp;
  return { gross: (grossRent / price) * 100, net: (net / (price + c)) * 100, annualNet: net, monthlyNet: net / 12, collected, invested: price + c };
}
